import { useState } from 'react';
import type { FormEvent } from 'react';
import {
  JxStepper,
  JxInputField,
  JxSelect,
  JxButton,
  JxDivider,
  JxTable,
} from '@jinx-ui/react';

type SignupValues = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type SignupWizardProps = {
  onSubmit: (values: SignupValues) => void;
};

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

const countries = [
  { value: 'ru', label: 'Россия' },
  { value: 'kz', label: 'Казахстан' },
  { value: 'by', label: 'Беларусь' },
  { value: 'am', label: 'Армения' },
];

const emptyValues: SignupValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

function SignupWizard({ onSubmit }: SignupWizardProps) {
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<SignupValues>(emptyValues);
  const [errors, setErrors] = useState<Partial<Record<keyof SignupValues, string>>>({});

  const setField = (field: keyof SignupValues) => (value: string) => {
    setValues((prev) => ({ ...prev, [field]: value }));
    setErrors((prev) => ({ ...prev, [field]: undefined }));
  };

  const validate = (index: number) => {
    const next: Partial<Record<keyof SignupValues, string>> = {};

    if (index === 0) {
      if (!values.name.trim()) next.name = 'Укажите имя';
      if (!values.email.trim()) next.email = 'Укажите почту';
      else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email)) next.email = 'Проверьте формат почты';
    }

    if (index === 1) {
      if (!values.country) next.country = 'Выберите страну';
      if (!values.city.trim()) next.city = 'Укажите город';
      if (!values.street.trim()) next.street = 'Укажите улицу и дом';
    }

    setErrors(next);
    return Object.keys(next).length === 0;
  };

  const goBack = () => {
    setErrors({});
    setStep((prev) => Math.max(prev - 1, 0));
  };

  const goNext = () => {
    if (!validate(step)) return;
    setStep((prev) => Math.min(prev + 1, steps.length - 1));
  };

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();

    if (step < steps.length - 1) {
      goNext();
      return;
    }

    if (!validate(0) ) {
      setStep(0);
      return;
    }

    if (!validate(1)) {
      setStep(1);
      return;
    }

    onSubmit(values);
  };

  const countryLabel = countries.find((item) => item.value === values.country)?.label ?? '—';

  return (
    <form
      onSubmit={submit}
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        padding: '24px',
        maxWidth: '520px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
        color: 'var(--jx-text)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      <JxDivider />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Имя"
            required
            value={values.name}
            onChange={(event) => setField('name')(event.target.value)}
            errorText={errors.name}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={values.email}
            onChange={(event) => setField('email')(event.target.value)}
            errorText={errors.email}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            placeholder="900 000-00-00"
            helperText="Не обязательно"
            value={values.phone}
            onChange={(event) => setField('phone')(event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxSelect
            label="Страна"
            placeholder="Выберите страну"
            options={countries}
            value={values.country}
            onValueChange={setField('country')}
          />
          {errors.country && (
            <span className="jx-input-error" style={{ color: 'var(--jx-danger)' }}>
              {errors.country}
            </span>
          )}
          <JxInputField
            label="Город"
            required
            value={values.city}
            onChange={(event) => setField('city')(event.target.value)}
            errorText={errors.city}
          />
          <JxInputField
            label="Улица и дом"
            required
            value={values.street}
            onChange={(event) => setField('street')(event.target.value)}
            errorText={errors.street}
          />
          <JxInputField
            label="Индекс"
            inputMode="numeric"
            value={values.zip}
            onChange={(event) => setField('zip')(event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <JxTable>
          <tbody>
            <tr>
              <td style={{ color: 'var(--jx-text-2)' }}>Имя</td>
              <td>{values.name || '—'}</td>
            </tr>
            <tr>
              <td style={{ color: 'var(--jx-text-2)' }}>Почта</td>
              <td>{values.email || '—'}</td>
            </tr>
            <tr>
              <td style={{ color: 'var(--jx-text-2)' }}>Телефон</td>
              <td>{values.phone ? `+7 ${values.phone}` : '—'}</td>
            </tr>
            <tr>
              <td style={{ color: 'var(--jx-text-2)' }}>Страна</td>
              <td>{countryLabel}</td>
            </tr>
            <tr>
              <td style={{ color: 'var(--jx-text-2)' }}>Город</td>
              <td>{values.city || '—'}</td>
            </tr>
            <tr>
              <td style={{ color: 'var(--jx-text-2)' }}>Адрес</td>
              <td>{values.street || '—'}</td>
            </tr>
            <tr>
              <td style={{ color: 'var(--jx-text-2)' }}>Индекс</td>
              <td>{values.zip || '—'}</td>
            </tr>
          </tbody>
        </JxTable>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton variant="ghost" type="button" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" type="button" onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" type="submit">
            Отправить
          </JxButton>
        )}
      </div>
    </form>
  );
}

export default SignupWizard;

